import XCTest
@testable import EmperorCore

/// The composer and export options, held to the platform's own JavaScript.
///
/// `Resources/composer/` is generated by running the web's files under Node
/// (`scripts/generate-draft-depth-fixtures.mjs`, `generate-research-sources-fixtures.mjs`,
/// `generate-page-setup-fixtures.mjs`). When one of these fails after a platform change,
/// regenerate; never edit the fixture to match.
final class ComposerOptionsGoldenTests: XCTestCase {

    private func fixture(_ name: String) throws -> [String: Any] {
        let url = try XCTUnwrap(
            Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "composer"))
        return try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    // MARK: Draft length

    func testTheLengthLinesAreTheWebsWordForWord() throws {
        let f = try fixture("draft-depth")
        let lines = try XCTUnwrap(f["lengthLine"] as? [String: String])
        XCTAssertEqual(DraftDepth.short.lengthLine, lines["short"])
        XCTAssertEqual(DraftDepth.detailed.lengthLine, lines["otherwise"])
    }

    func testTheChoicesAndTheDefaultAreTheWebs() throws {
        let f = try fixture("draft-depth")
        XCTAssertEqual(DraftDepth.default.rawValue, f["default"] as? String)
        XCTAssertEqual(DraftDepth.default.rawValue, f["workspaceFallback"] as? String)
        let depths = try XCTUnwrap(f["depths"] as? [[String: String]])
        XCTAssertEqual(DraftDepth.allCases.map(\.rawValue), depths.map { $0["id"] ?? "" })
        XCTAssertEqual(DraftDepth.allCases.map(\.label), depths.map { $0["label"] ?? "" })
        XCTAssertEqual(DraftDepth.allCases.map(\.hint), depths.map { $0["hint"] ?? "" })
    }

    /// The line goes straight after the tool's prompt and the attached-record line. This client's
    /// tool form has no record line, so it follows the tool's prompt directly; if the web ever
    /// moves it, this fails and `ToolSpec.draftPrompt` has to move with it.
    func testTheLengthLineFollowsTheToolPromptAndTheRecordLine() throws {
        let order = try XCTUnwrap(try fixture("draft-depth")["promptOrder"] as? [String])
        XCTAssertEqual(Array(order.prefix(3)), ["tool.buildPrompt(values2)", "recordLine", "lengthLine"])
    }

    func testADraftPromptIsTheToolPromptThenTheLengthLine() throws {
        let tool = try XCTUnwrap(LEGAL_TOOLS.first)
        let values = ToolValues(["forum": "NCLT"])
        let day = Date(timeIntervalSince1970: 1_788_000_000)
        XCTAssertEqual(
            tool.draftPrompt(values, depth: .short, today: day),
            tool.prompt(values, today: day) + DraftDepth.short.lengthLine)
        XCTAssertTrue(tool.draftPrompt(values, depth: .detailed, today: day)
            .hasSuffix("leave nothing material unaddressed."))
    }

    // MARK: Research sources

    func testTheSourcesAreTheWebsInItsOrder() throws {
        let f = try fixture("research-sources")
        let web = try XCTUnwrap(f["web"] as? [String: String])
        XCTAssertEqual(ResearchSources.web.id, web["id"])
        XCTAssertEqual(ResearchSources.web.label, web["label"])

        func check(_ ours: [ResearchSource], _ theirs: Any?, file: StaticString = #filePath, line: UInt = #line) throws {
            let rows = try XCTUnwrap(theirs as? [[String: Any]])
            XCTAssertEqual(ours.map(\.id), rows.map { $0["id"] as? String ?? "" }, file: file, line: line)
            XCTAssertEqual(ours.map(\.label), rows.map { $0["label"] as? String ?? "" }, file: file, line: line)
            for (row, theirs) in zip(ours, rows) {
                // A flag where the web draws a flag, an icon where it draws an icon.
                XCTAssertEqual(row.flag, theirs["flag"] as? String, row.id, file: file, line: line)
                XCTAssertEqual(row.systemImage != nil, theirs["icon"] is String, row.id, file: file, line: line)
            }
        }
        try check(ResearchSources.jurisdictions, f["jurisdictions"])
        try check(ResearchSources.repositories, f["repositories"])
        XCTAssertEqual(f["sections"] as? [String], ["Jurisdictions", "Repositories"])
    }

    /// India on, as the web starts. Web search is the one deliberate difference: on the web the
    /// row is preference state only, here it asks the server for a search on every question.
    func testTheDefaultIsTheWebsWithWebSearchLeftOff() throws {
        let theirs = try XCTUnwrap(try fixture("research-sources")["defaultSelection"] as? [String: Bool])
        let webOn = Set(theirs.filter(\.value).map(\.key))
        XCTAssertEqual(webOn, ["web", "in"], "the web's default moved; revisit `ResearchSources.default`")
        XCTAssertEqual(ResearchSources.default.selected, webOn.subtracting([ResearchSources.webID]))
        XCTAssertFalse(ResearchSources.default.searchesWeb)
    }

    // MARK: Page setup

    func testTheSizesOrientationsAndDefaultsAreTheWebs() throws {
        let f = try fixture("page-setup")
        let sizes = try XCTUnwrap(f["sizes"] as? [[String: Any]])
        XCTAssertEqual(DocumentPageSize.all.map(\.id), sizes.map { $0["id"] as? String ?? "" })
        XCTAssertEqual(DocumentPageSize.all.map(\.label), sizes.map { $0["label"] as? String ?? "" })
        XCTAssertEqual(DocumentPageSize.all.map(\.widthMM), sizes.map { $0["width"] as? Double ?? -1 })
        XCTAssertEqual(DocumentPageSize.all.map(\.heightMM), sizes.map { $0["height"] as? Double ?? -1 })

        let orientations = try XCTUnwrap(f["orientations"] as? [[String: String]])
        XCTAssertEqual(DocumentPageOrientation.allCases.map(\.rawValue), orientations.map { $0["id"] ?? "" })
        XCTAssertEqual(DocumentPageOrientation.allCases.map(\.label), orientations.map { $0["label"] ?? "" })

        let margins = try XCTUnwrap(f["defaultMargins"] as? [String: Double])
        XCTAssertEqual(DocumentPageMargins.default, DocumentPageMargins(
            top: margins["top"]!, right: margins["right"]!, bottom: margins["bottom"]!, left: margins["left"]!))
        XCTAssertEqual(DocumentPageSetup.default, DocumentPageSetup(size: .a4, orientation: .portrait, margins: .default))
    }

    func testMillimetresBecomeTwipsAsTheWebRoundsThem() throws {
        let rows = try XCTUnwrap(try fixture("page-setup")["mmTwip"] as? [[String: Double]])
        XCTAssertGreaterThan(rows.count, 10)
        for row in rows {
            XCTAssertEqual(DocumentPageSetup.twips(row["mm"]!), Int(row["twip"]!), "\(row["mm"]!)mm")
        }
    }

    /// Every stored shape — partial, legacy, nonsense — normalises as the web's `normalizePageSetup`
    /// does, and lands in Word as the web's exporter writes it.
    func testEveryStoredShapeNormalisesAndMeasuresAsTheWebsDoes() throws {
        let cases = try XCTUnwrap(try fixture("page-setup")["cases"] as? [[String: Any]])
        XCTAssertGreaterThan(cases.count, 10)
        for c in cases {
            let input = try JSONSerialization.data(withJSONObject: c["input"] ?? NSNull(), options: [.fragmentsAllowed])
            let setup = try JSONDecoder().decode(DocumentPageSetup.self, from: input)
            let name = String(decoding: input, as: UTF8.self)

            let normal = try XCTUnwrap(c["normalized"] as? [String: Any])
            XCTAssertEqual(setup.size.id, normal["size"] as? String, name)
            XCTAssertEqual(setup.orientation.rawValue, normal["orientation"] as? String, name)
            let m = try XCTUnwrap(normal["margins"] as? [String: Double])
            XCTAssertEqual(setup.margins, DocumentPageMargins(
                top: m["top"]!, right: m["right"]!, bottom: m["bottom"]!, left: m["left"]!), name)

            let dims = try XCTUnwrap(c["dimensions"] as? [String: Double])
            XCTAssertEqual(setup.widthMM, dims["width"]!, name)
            XCTAssertEqual(setup.heightMM, dims["height"]!, name)
            let content = try XCTUnwrap(c["contentMm"] as? [String: Double])
            XCTAssertEqual(setup.contentWidthMM, content["width"]!, accuracy: 1e-9, name)
            XCTAssertEqual(setup.contentHeightMM, content["height"]!, accuracy: 1e-9, name)
            XCTAssertEqual(setup.label, c["label"] as? String, name)

            let docx = try XCTUnwrap(c["docx"] as? [String: Any])
            XCTAssertEqual(setup.sheetTwips.width, docx["width"] as? Int, name)
            XCTAssertEqual(setup.sheetTwips.height, docx["height"] as? Int, name)
            XCTAssertEqual(setup.isLandscape, (docx["orientation"] as? String) == "landscape", name)
            let twips = try XCTUnwrap(docx["margins"] as? [String: Int])
            XCTAssertEqual(setup.marginTwips.top, twips["top"], name)
            XCTAssertEqual(setup.marginTwips.right, twips["right"], name)
            XCTAssertEqual(setup.marginTwips.bottom, twips["bottom"], name)
            XCTAssertEqual(setup.marginTwips.left, twips["left"], name)
        }
    }
}
